Translate("esES", "marshal-dughan", {
	title = "Mariscal Dughan",
	subtitle = "Mariscal de Villadorada",
	found = "Villadorada, ante la posada Lion's Pride",
	hint = "Hable con el mariscal que vigila Villadorada.",
	allegiance = "Reino de Ventormenta · Ejército de Ventormenta",
	aliases = { "Dughan" },
	sections = {
		{
			title = "Resumen",
			text = [=[Desde el pueblo de {link:goldshire}Villadorada{/link}, en el cruce de caminos, el mariscal Dughan dirige la defensa del {link:elwynn-forest}Bosque de Elwynn{/link}. Sus soldados son demasiado pocos para la tarea. Aun así, debe mantener abiertos los caminos que unen la capital con sus granjas, sus molinos y sus minas. Cada recluta que sale de la {link:northshire-abbey}Abadía de Villanorte{/link} pasa por sus manos, y él envía a cada uno allí donde el bosque sangra más.]=],
		},
		{
			title = "Importancia",
			text = [=[Dughan es el rostro de un reino llevado al límite. {link:stormwind-city}Ventormenta{/link} no tiene rey en el trono, ni ejército a mano, y solo cuenta con la lealtad de hombres y mujeres corrientes para mantener su paz. Él no se queja de ello. Simplemente hace el trabajo que queda.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Defiende {link:elwynn-forest}Elwynn{/link} con un puñado de soldados, repartidos entre {link:goldshire}Villadorada{/link}, el {link:westbrook-garrison}Cuartel Arroyoeste{/link} y {link:stranglethorn-vale}la Vega{/link} del Este.
• Envía exploradores a la {link:fargodeep-mine}Mina Abisal{/link} y a la {link:jasperlode-mine}Cantera de Jaspe{/link}, donde los kóbolds se envalentonan cada día.
• Pone precio a la cabeza del {link:gnolls}gnoll{/link} {link:hogger}Hogger{/link} y a los asaltantes {link:riverpaw-gnolls}Zarparrío{/link} de la frontera del sur.
• Envía la ayuda que puede a los puestos apartados del bosque, aunque rara vez le sobra alguna.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito sobre la vida de Dughan antes de {link:goldshire}Villadorada{/link}. Esta entrada recoge solo lo que revelan sus hazañas y su puesto.]=],
		},
	},
	chapters = {
		{
			title = "Los reclutas de Villanorte",
			hint = [=[Termine su entrenamiento en Villanorte y preséntese en Villadorada.]=],
			text = [=[Los reclutas llegan con cartas del mariscal {link:marshal-mcbride}McBride{/link}. Dughan tiene poco tiempo para recibirlos, porque los kóbolds dominan las minas, los gnolls merodean por la frontera y los ladrones rondan cada camino. Pone a trabajar a cada recién llegado en menos de una hora.]=],
		},
		{
			title = "Bajo las colinas",
			hint = "Investigue las minas de Elwynn en nombre del mariscal.",
			text = [=[Los informes de la {link:fargodeep-mine}Mina Abisal{/link} y de la {link:jasperlode-mine}Cantera de Jaspe{/link} confirman lo que Dughan temía. Los kóbolds ya no son una molestia que se expulsa con antorchas. Se están extendiendo, y excavan más hondo de lo que ningún minero honrado se atrevió nunca.]=],
		},
		{
			title = "La frontera del sur",
			hint = "Ocúpese del asunto de Hogger.",
			text = [=[Durante mucho tiempo, las historias de {link:hogger}Hogger{/link} se contaron como cuentos junto al fuego. Dughan dejó de tratarlas como cuentos cuando los muertos empezaron a volver a casa desde las granjas del sur.]=],
		},
		{
			title = "El Recaudador",
			hint = "Siga el oro robado de las minas hasta su destino.",
			text = [=[El polvo de oro robado de las minas no se queda con los kóbolds. Viaja por caminos ocultos hasta un agente {link:defias-brotherhood}Defias{/link} conocido solo como el Recaudador. Cuando se encuentra el anillo del Recaudador, lleva la marca del antiguo {link:stonemasons-guild}Gremio de Canteros{/link} de {link:stormwind-city}Ventormenta{/link}. Dughan comprende entonces que los ladrones de {link:elwynn-forest}Elwynn{/link} no son bandidos corrientes. Son los canteros a los que Ventormenta traicionó.]=],
		},
	},
	mentions = {
		{
			text = [=[Informar a {link:goldshire}Villadorada{/link}, llevado desde el mariscal {link:marshal-mcbride}McBride{/link}]=],
		},
		{ text = "La {link:fargodeep-mine}Mina Abisal{/link}" },
		{ text = "La {link:jasperlode-mine}Cantera de Jaspe{/link}" },
		{
			text = [=[¡El {link:westbrook-garrison}Cuartel Arroyoeste{/link} necesita ayuda!]=],
		},
		{
			text = [=[Se busca: {link:hogger}Hogger{/link}, una recompensa pagada de su mano]=],
		},
		{
			text = [=[Un peligro con escamas, traído por {link:remy-two-times}Remy "Two Times"{/link}]=],
		},
		{ text = "Cacería humana" },
		{ text = "¡Chsss! Estamos cazando kóbolds" },
		{ text = "Devolución de libros" },
		{ text = "Libros raros" },
	},
	bonds = {
		{ id = "marshal-mcbride", name = "Mariscal McBride", note = "le envía reclutas" },
		{ id = "deputy-rainer", name = "Ayudante Rainer", note = "defiende el Cuartel Arroyoeste" },
		{ id = "guard-thomas", name = "Guardia Thomas", note = "vigila la Vega del Este" },
		{ id = "remy-two-times", name = "Remy \"Two Times\"", note = "le trae noticias" },
		{ id = "hogger", name = "Hogger", note = "enemigo" },
	},
})

