	allegiance = "Reino de Ventormenta (retirado)",
	aliases = { "Haggard" },
	sections = {
		{
			title = "Resumen",
			text = [=[El mariscal Haggard sirvió a {link:stormwind-city}Ventormenta{/link} durante muchos años antes de retirarse a una mansión cerca de {link:stranglethorn-vale}la Vega{/link} del Este. Sus ojos se han debilitado con la edad, pero no su orgullo. Todavía conserva la insignia de su cargo, y todavía conoce viejas historias que los soldados más jóvenes han olvidado.]=],
