		{
			title = "Importancia",
			text = [=[Haggard es una memoria viva de la antigua {link:stormwind-city}Ventormenta{/link}. Su casa guarda también el primer hilo de una historia más oscura, que lleva al este, a {link:duskwood}Bosque del Ocaso{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Sirvió como mariscal de {link:stormwind-city}Ventormenta{/link} hasta su retiro.
• Conoce la vieja historia de un hombre llamado {link:stalvan-mistmantle}Stalvan{/link}, una historia que empieza con una caja sellada hallada en los canales de Ventormenta.]=],
		},
	},
	chapters = {
		{
			title = "El ladrón en la oscuridad",
			hint = "Recupere lo que le robaron al viejo mariscal.",
			text = [=[Una noche, un hombre con un tabardo de {link:stormwind-city}Ventormenta{/link} llamó a la puerta de Haggard. En la oscuridad, el viejo mariscal lo tomó por {link:marshal-dughan}Dughan{/link} y le entregó su insignia. El visitante no era ningún mariscal. Era un ladrón {link:defias-brotherhood}Defias{/link} llamado Dead-tooth Jack, y desapareció con la insignia antes del alba.]=],
		},
		{
			title = "La caja sellada",
			hint = [=[Lleve al viejo mariscal lo que se encontró en una caja sellada en los canales de Ventormenta.]=],
			text = [=[Una caja sellada, largo tiempo olvidada en los canales de {link:stormwind-city}Ventormenta{/link}, contenía papeles que señalaban al mariscal Haggard. Cuando llegaron a sus manos, el viejo mariscal reconoció el nombre del que hablaban. Aquello dio comienzo a una historia que preferiría no recordar: la leyenda de {link:stalvan-mistmantle}Stalvan Mistmantle{/link}, un nombre que todavía se susurra con temor en {link:duskwood}Bosque del Ocaso{/link}.]=],
		},
	},
	mentions = {
		{ text = "Mariscal Haggard" },
		{ text = "Dead-tooth Jack" },
		{ text = "La leyenda de {link:stalvan-mistmantle}Stalvan{/link}" },
	},
	bonds = {
